// =============================================================
// Noellyne AI — app chat endpoint (reuses the Hermes brain)
// Webhook POST { message, history[] } -> { reply }
// Provider chain: Groq -> Gemini -> OpenRouter, with per-key cooldowns.
// =============================================================
const body = $input.first().json || {};
const question = String(body.message || body.text || '').trim();
if (!question) return [{ json: { reply: 'Uliza swali kuhusu mechi, picks au mtaji.' } }];

const sd = $getWorkflowStaticData('global');
const picks =
  sd.lastPicksText ||
  'Hakuna picks zilizohifadhiwa bado. Picks huwekwa saa 09:00 / 14:00 / 19:00 EAT.';

const SYS =
  'Wewe ni Noellyne Hermes Sports AI — mshauri wa Football na NBA betting. ' +
  'Jibu kwa Kiswahili safi, ufupi (mistari 4-8), bila Markdown (* au **) wala HTML. ' +
  'Tumia picks zilizotolewa kama chanzo cha ukweli.';
const prompt = `PICKS ZA LEO:\n${picks}\n\nUJUMBE WA MTUMIAJI:\n"${question}"`;

const MAX_TOK = 700;
const DEADLINE = Date.now() + 30000;
const ENV_MAP = { groq: 'GROQ_KEYS', gemini: 'GEMINI_KEYS', openrouter: 'OPENROUTER_KEYS' };
const URLS = {
  groq: 'https://api.groq.com/openai/v1/chat/completions',
  openrouter: 'https://openrouter.ai/api/v1/chat/completions',
};
const MODELS = {
  groq: ['openai/gpt-oss-120b', 'llama-3.3-70b-versatile'],
  gemini: ['gemini-2.5-flash'],
  openrouter: ['nvidia/nemotron-nano-9b-v2:free'],
};
sd.rr = sd.rr || {};
sd.cool = sd.cool || {};
const now = () => Date.now();
const keysOf = (p) => String($env[ENV_MAP[p]] || '').split(',').map((s) => s.trim()).filter(Boolean);
const isCool = (p, i) => (sd.cool[`${p}:${i}`] || 0) > now();
const cool = (p, i, ms) => { sd.cool[`${p}:${i}`] = now() + ms; };
const nextIdx = (p, len) => { const c = Number.isFinite(sd.rr[p]) ? sd.rr[p] : -1; const n = (c + 1) % len; sd.rr[p] = n; return n; };

async function callOpenAi(prov, model, key) {
  const payload = {
    model,
    messages: [
      { role: 'system', content: SYS },
      { role: 'user', content: prompt },
    ],
    temperature: 0.3,
  };
  if (/gpt-oss/.test(model)) { payload.max_completion_tokens = MAX_TOK; payload.reasoning_effort = 'low'; }
  else payload.max_tokens = MAX_TOK;
  const headers = { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' };
  if (prov === 'openrouter') headers['HTTP-Referer'] = 'https://noellyne.bet';
  const r = await this.helpers.httpRequest({
    method: 'POST', url: URLS[prov], headers, body: payload, json: true,
    returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000,
  });
  return { status: r.statusCode, text: r.body?.choices?.[0]?.message?.content };
}

async function callGemini(model, key) {
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`,
    headers: { 'x-goog-api-key': key, 'Content-Type': 'application/json' },
    body: {
      system_instruction: { parts: [{ text: SYS }] },
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: { maxOutputTokens: MAX_TOK, temperature: 0.3 },
    },
    json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000,
  });
  const parts = r.body?.candidates?.[0]?.content?.parts || [];
  return { status: r.statusCode, text: parts.map((p) => p.text).join('') };
}

for (const prov of ['groq', 'gemini', 'openrouter']) {
  if (now() > DEADLINE) break;
  const keys = keysOf(prov);
  if (!keys.length) continue;
  for (const model of MODELS[prov]) {
    if (now() > DEADLINE) break;
    for (let a = 0; a < Math.min(keys.length, 2); a++) {
      const idx = nextIdx(prov, keys.length);
      if (isCool(prov, idx)) continue;
      try {
        const res = prov === 'gemini'
          ? await callGemini.call(this, model, keys[idx])
          : await callOpenAi.call(this, prov, model, keys[idx]);
        if (res.status >= 200 && res.status < 300 && res.text) {
          return [{ json: { reply: String(res.text).trim(), provider: prov, model } }];
        }
        cool(prov, idx, res.status === 429 ? 60000 : 25000);
      } catch (e) {
        cool(prov, idx, 20000);
      }
    }
  }
}

return [{ json: { reply: '⚠️ AI iko busy kwa sasa. Jaribu tena baada ya sekunde chache, au angalia tab ya Picks.' } }];
